 if(id==='check')return `${head('Check','Every quote is compared with the recording, word for word.')}<p class="d-waits">${ICON.wait}Waits for the words to be finished.</p><div class="d-row"><button class="btn" data-act="set:step:words">Go to the words${icon('right')}</button></div>`;
 if(id==='yes')return `${head('Mrs. Oda’s yes','She is named, quoted four times and in two photographs.')}${S.ui.consent?`<p class="d-loose ok">${icon('check')}<span>The request is drafted. Send it from Share when you are ready.</span><button class="btn" data-act="ui:consent:asked">${icon('undo')}Undo</button></p>`:`<article class="d-one"><p>Nothing can be published or posted until she has answered.</p><div class="d-row"><button class="btn pri" data-act="ui:consent:asked">Draft the request to her</button><button class="btn" data-act="noop">She already said yes</button></div></article>`}`;
 if(id==='publish'||id==='post')return `${head(id==='post'?'Post to Instagram':'Publish to the magazine','')}<ul class="d-waitl">${(id==='post'?[['yes','Her yes',S.ui.consent],['slides','The slides',S.ui.pick],['captions','Captions',false]]:[['yes','Her yes',S.ui.consent],['check','The check',false]]).map(([k,n,ok])=>`<li class="${ok?'ok':''}">${ok?ICON.done:ICON.wait}<span>${n}</span><button class="d-link" data-act="set:step:${k}">Open${icon('chev')}</button></li>`).join('')}</ul>${id==='post'?'<p class="d-meta">Posting is not connected. When this is ready, the slides and the text can be saved to your phone.</p>':''}`;
 if(id==='slides'){const sel=S.ui.tpl||'Photo above';return `${head('The slides',S.ui.pick?'All five are ready.':'Slide 4 needs a photograph.')}<div class="d-slides5">${K.slidesData.map((d,i)=>i===3?`<div class="d-slot4 on">${S.ui.pick?`<div class="sl half">${K.photo(S.ui.pick,'Slide photograph')}<span><b>${esc(d.text)}</b></span></div>`:K.slide(3)}</div>`:`<div>${K.slide(i)}</div>`).join('')}</div>
 <div class="d-pickrow"><div><p class="d-label">Photograph for slide 4</p><div class="d-tray pick">${K.photos.map(([k,l])=>`<button data-act="ui:pick:${k}" aria-pressed="${S.ui.pick===k}" title="${esc(l)}">${K.pic(k,l)}</button>`).join('')}</div></div>
 <div><p class="d-label">Template for slide 4</p><div class="d-tpls">${TPL.map(([n,k])=>`<button data-act="set:tpl:${n}" aria-pressed="${sel===n}"><i class="${k}"></i>${n}</button>`).join('')}</div></div></div>
 <div class="d-row"><button class="btn" data-act="noop">Edit the words on the slides</button><button class="btn" data-act="noop">Change the order</button></div>`;}
 if(id==='captions')return `${head('Captions',S.ui.pick?'One line under each photograph.':'')}${S.ui.pick?`<ul class="d-caps">${[['shade','Straw shades at dawn'],['hands','Her hands, sorting'],[S.ui.pick,'']].map(([k,c])=>`<li>${K.pic(k,'')}<span class="d-field">${c||'Write a caption'}</span></li>`).join('')}</ul>`:`<p class="d-waits">${ICON.wait}Waits for the photograph on slide 4.</p><div class="d-row"><button class="btn" data-act="set:step:slides">Go to the slides${icon('right')}</button></div>`}`;
