function formPicker(S){if(S.ui.sheet!=='form')return '';return `<div class="scrim" data-act="set:sheet:"><div class="sheet d-formpick" role="dialog" aria-label="Add a form" data-stop><h3>What else will this be?</h3><p class="to">Each form brings its own steps and your template for it.</p><div>${ADD.map(([n,to,d,needs])=>`<button data-act="${n==='Video'?'addvideo':'set:sheet:'}"><b>${n}</b><small>for ${to}</small><span>${d}</span><em>Needs: ${needs}</em></button>`).join('')}</div></div></div>`;}
function subject(S){const forms=formsOf(S),fid=forms.find(x=>x.id===S.ui.form)?S.ui.form:forms[0].id,st=stepsOf(S,fid),sid=S.ui.step=(st.find(x=>x.id===S.ui.step)?S.ui.step:firstOpen(st)),groups=['Gather','Research','Simmer','Create','Share'];
 return `<div class="d-sub2"><header class="d-sub-h"><div><h1>${esc(SUB.name)}</h1><p class="d-path" title="This is a real folder on disk">Subjects / Tea / ${esc(SUB.name)}</p></div><p class="d-about"><span>${esc(K.direction)}</span><button class="d-link" data-act="set:step:dish">Change</button></p></header>
 <div class="d-forms" data-drop="form:end">${forms.map((f,i)=>{const fs=stepsOf(S,f.id);return `<button class="d-form${f.id===fid?' on':''}" data-act="form:${f.id}" draggable="true" data-drag="form:${i}" data-drop="form:${i}">${GRIP}<small>${i===0?'First':i===1?'Then':'After that'}</small><b>${f.name}</b><span>for ${f.to} · ${f.tpl}</span><em>${ring(prog(fs))}${fs.filter(x=>x.st==='done').length} of ${fs.length} steps</em></button>`;}).join('')}<button class="d-form add" data-act="set:sheet:form">${icon('plus')}<b>Add a form</b><span>Post, Story, Video, Product listing…</span></button></div>
 <div class="d-work"><nav class="d-path2" aria-label="Steps to the finish line">${groups.map(g=>{const rows=st.filter(x=>x.g===g);return rows.length?`<p>${g}</p><ol>${rows.map(x=>`<li class="${x.st}${x.id===sid?' on':''}"><button data-act="set:step:${x.id}">${ICON[x.st]}<b>${x.n}</b><small>${esc(x.note)}</small></button>${x.id===sid?`<div class="d-inl">${detail(S,fid,sid,st)}${nextUp(st,sid)}</div>`:''}</li>`).join('')}</ol>`:'';}).join('')}</nav>
 <section class="d-stepv">${detail(S,fid,sid,st)}${nextUp(st,sid)}</section></div></div>${formPicker(S)}`;}
const nextUp=(st,sid)=>{const cur=st.find(x=>x.id===sid);if(cur.st!=='done')return '';const nx=st.find(x=>x.st==='now')||st.find(x=>x.st==='todo'||x.st==='flag');return nx?`<footer class="d-nextup"><span>${ICON.done}This step is done.</span><button class="btn pri" data-act="set:step:${nx.id}">Next: ${esc(nx.n)}${icon('right')}</button></footer>`:'';};
function fresh(S){
 return `<div class="d-sub2"><header class="d-sub-h"><div><h1>${esc(S.newName)}</h1><p class="d-path">Subjects / Tea / ${esc(S.newName)}</p></div></header>
 <div class="d-forms"><div class="d-form none"><b>Not decided yet</b><span>Gather first. Say what it will be when you know.</span></div><button class="d-form add" data-act="set:sheet:form">${icon('plus')}<b>Add a form</b><span>Article, Carousel, Post, Video…</span></button></div>
 <div class="d-work"><nav class="d-path2"><p>Gather</p><ol><li class="now on"><button data-act="noop">${ICON.now}<b>What you have</b><small>Nothing yet</small></button><div class="d-inl">${freshHave()}</div></li></ol><p>Simmer</p><ol><li class="wait"><button data-act="noop">${ICON.wait}<b>Name the dish</b><small>When there is something to look at</small></button></li></ol><p class="later">The rest appears when you say what it will be.</p></nav>
 <section class="d-stepv">${freshHave()}</section></div></div>${formPicker(S)}${K.newSheet()}`;}
const freshHave=()=>`<header><p class="d-label">Gather</p><h2>What you have</h2></header><div class="d-ways"><button data-act="capture:subject">${icon('mic')}<b>A recording</b><span>Record now, or add one.</span></button><button data-act="capture:subject">${icon('note')}<b>A note or a link</b><span>A thought, a page, a video.</span></button><button data-act="capture:subject">${icon('photo')}<b>Photographs</b><span>From this device or the Library.</span></button></div><button class="d-drop" data-act="capture:subject">${icon('plus')}Or drop anything here</button>`;
