const MADE=[['Reed screens: who still makes them','talk','Mrs. Oda’s recording, 21:04','Tea: growing',3,''],['Soil under straw','check','Twenty days of shade, one voice only','Tea: growing',1,''],['Why the sand is swept away','saves','4 things you saved this month','Mandala',4,'Suggested group'],['Charcoal and iron kettles','note','A kettle for charcoal','',2,'']];
